window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-be490f5b87a8c8d1"]={"versions": [{"id": "FIG-be490f5b87a8c8d1", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles Metamodell-/Strukturdiagramm aus der AUTOSAR-Spezifikation des Software-Component-Templates (<code>AUTOSAR_TPS_SoftwareComponentTemplate</code>). Das Diagramm illustriert das formale Modellierungskonzept zur Wertespezifikation eines eindimensionalen Arrays (<code>ArrayValueSpecification</code>) und dessen Zerlegung in einzelne Array-Elemente.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Umschließendes Array-Element (<code>array</code>)</strong>: Repräsentiert die übergeordnete Datenstruktur bzw. die Instanz einer <code>ArrayValueSpecification</code>.\n</li><li><strong>Array-Zellen / Elemente (drei Blöcke <code>a</code>)</strong>: Drei sequenziell angeordnete Teilblöcke gleicher Struktur, die jeweils ein einzelnes Array-Element symbolisieren.\n</li><li><strong>Positions- bzw. Wertmarkierungen (ovale Badges)</strong>: Drei dunkle Ovale an den oberen Kanten der Zellen mit den Werten <code>1</code>, <code>0</code> und <code>0</code>, die Indizes oder Initialwerte/Belegungsmuster der jeweiligen Array-Elemente kennzeichnen.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Datenstrukturdiagramm ohne zeitlichen oder sequenziellen Kontrollfluss. Die Darstellung beschreibt die statische Zuordnung und Aggregation von Array-Elementen innerhalb einer übergeordneten Wertespezifikation.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Dient der formalen Spezifikation von Initialwerten oder Konstanten für Array-Datentypen im AUTOSAR-Softwarekomponentenmodell. Entwickler und Generatoren müssen sicherstellen, dass bei der Definition einer <code>ArrayValueSpecification</code> die Anzahl und Typisierung der Unterelemente (<code>ValueSpecification</code>) exakt mit der Dimensionierung des korrespondierenden <code>ImplementationDataType</code> bzw. <code>ApplicationArrayDataType</code> übereinstimmt.</p>"}, {"id": "FIG-3f66a53a3faeeebc", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles Metamodell-/Strukturdiagramm aus der AUTOSAR-Spezifikation des Software-Component-Templates (<code>AUTOSAR_TPS_SoftwareComponentTemplate</code>). Das Diagramm illustriert das formale Modellierungskonzept zur Wertespezifikation eines eindimensionalen Arrays (<code>ArrayValueSpecification</code>) und dessen Zerlegung in einzelne Array-Elemente.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Umschließendes Array-Element (<code>array</code>)</strong>: Repräsentiert die übergeordnete Datenstruktur bzw. die Instanz einer <code>ArrayValueSpecification</code>.\n</li><li><strong>Array-Zellen / Elemente (drei Blöcke <code>a</code>)</strong>: Drei sequenziell angeordnete Teilblöcke gleicher Struktur, die jeweils ein einzelnes Array-Element symbolisieren.\n</li><li><strong>Positions- bzw. Wertmarkierungen (ovale Badges)</strong>: Drei dunkle Ovale an den oberen Kanten der Zellen mit den Werten <code>1</code>, <code>0</code> und <code>0</code>, die Indizes oder Initialwerte/Belegungsmuster der jeweiligen Array-Elemente kennzeichnen.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Datenstrukturdiagramm ohne zeitlichen oder sequenziellen Kontrollfluss. Die Darstellung beschreibt die statische Zuordnung und Aggregation von Array-Elementen innerhalb einer übergeordneten Wertespezifikation.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Dient der formalen Spezifikation von Initialwerten oder Konstanten für Array-Datentypen im AUTOSAR-Softwarekomponentenmodell. Entwickler und Generatoren müssen sicherstellen, dass bei der Definition einer <code>ArrayValueSpecification</code> die Anzahl und Typisierung der Unterelemente (<code>ValueSpecification</code>) exakt mit der Dimensionierung des korrespondierenden <code>ImplementationDataType</code> bzw. <code>ApplicationArrayDataType</code> übereinstimmt.</p>"}, {"id": "FIG-38a53b6a630d5335", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles Metamodell-/Strukturdiagramm aus der AUTOSAR-Spezifikation des Software-Component-Templates (<code>AUTOSAR_TPS_SoftwareComponentTemplate</code>). Das Diagramm illustriert das formale Modellierungskonzept zur Wertespezifikation eines eindimensionalen Arrays (<code>ArrayValueSpecification</code>) und dessen Zerlegung in einzelne Array-Elemente.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Umschließendes Array-Element (<code>array</code>)</strong>: Repräsentiert die übergeordnete Datenstruktur bzw. die Instanz einer <code>ArrayValueSpecification</code>.\n</li><li><strong>Array-Zellen / Elemente</strong>: Drei unbeschriftete, sequenziell angeordnete Teilblöcke gleicher Struktur, die jeweils eine Speicherzelle bzw. ein Array-Element symbolisieren.\n</li><li><strong>Positions- bzw. Wertmarkierungen (ovale Badges)</strong>: Drei dunkle Ovale an den oberen Kanten der Zellen mit den Werten <code>1</code>, <code>0</code> und <code>0</code>, welche die Belegung bzw. Wertzuweisung der jeweiligen Array-Elemente indizieren.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Datenstrukturdiagramm ohne zeitlichen oder sequenziellen Kontrollfluss. Die Darstellung beschreibt die statische Zuordnung und Aggregation von Array-Elementen innerhalb einer übergeordneten Wertespezifikation.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Dient der formalen Spezifikation von Initialwerten oder Konstanten für Array-Datentypen im AUTOSAR-Softwarekomponentenmodell. Entwickler und Generatoren müssen sicherstellen, dass bei der Definition einer <code>ArrayValueSpecification</code> die Anzahl und Typisierung der Unterelemente (<code>ValueSpecification</code>) exakt mit der Dimensionierung des korrespondierenden <code>ImplementationDataType</code> bzw. <code>ApplicationArrayDataType</code> übereinstimmt.</p>"}, {"id": "FIG-24118fc996a4e309", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles Metamodell-/Strukturdiagramm aus der AUTOSAR-Spezifikation des Software-Component-Templates (<code>AUTOSAR_TPS_SoftwareComponentTemplate</code>). Das Diagramm illustriert das formale Modellierungskonzept zur Wertespezifikation eines eindimensionalen Arrays (<code>ArrayValueSpecification</code>) und dessen Zerlegung in einzelne Array-Elemente.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Umschließendes Array-Element (<code>array</code>)</strong>: Repräsentiert die übergeordnete Datenstruktur bzw. die Instanz einer <code>ArrayValueSpecification</code>.\n</li><li><strong>Array-Zellen / Elemente</strong>: Drei unbeschriftete, sequenziell angeordnete Teilblöcke gleicher Struktur, die jeweils eine Speicherzelle bzw. ein Array-Element symbolisieren.\n</li><li><strong>Positions- bzw. Wertmarkierungen (ovale Badges)</strong>: Drei dunkle Ovale an den oberen Kanten der Zellen mit den Werten <code>1</code>, <code>0</code> und <code>0</code>, welche die Belegung bzw. Wertzuweisung der jeweiligen Array-Elemente indizieren.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Datenstrukturdiagramm ohne zeitlichen oder sequenziellen Kontrollfluss. Die Darstellung beschreibt die statische Zuordnung und Aggregation von Array-Elementen innerhalb einer übergeordneten Wertespezifikation.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Dient der formalen Spezifikation von Initialwerten oder Konstanten für Array-Datentypen im AUTOSAR-Softwarekomponentenmodell. Entwickler und Generatoren müssen sicherstellen, dass bei der Definition einer <code>ArrayValueSpecification</code> die Anzahl und Typisierung der Unterelemente (<code>ValueSpecification</code>) exakt mit der Dimensionierung des korrespondierenden <code>ImplementationDataType</code> bzw. <code>ApplicationArrayDataType</code> übereinstimmt.</p>"}], "trans": [{"from": "FIG-be490f5b87a8c8d1", "to": "FIG-3f66a53a3faeeebc", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-3f66a53a3faeeebc", "to": "FIG-38a53b6a630d5335", "fr": "R19-11", "tr": "R20-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>In den drei Feldern des Arrays wurden die Beschriftungsbuchstaben „a“ entfernt.\n</li><li>Die untere Beschriftung „array“ sowie die Ziffernmarkierungen („1“, „0“, „0“) in den ovalen Badges wurden typografisch neu gerendert (geänderte Schriftart/Zeichenabstände).\n</li></ul>"}, {"from": "FIG-38a53b6a630d5335", "to": "FIG-24118fc996a4e309", "fr": "R20-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
